import json
import time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from email.utils import parsedate_to_datetime
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'
token = None
request_count = 0

def retry_delay(headers, attempt):
    value = headers.get('Retry-After') if headers else None
    if value:
        try:
            return max(0.0, float(value))
        except ValueError:
            try:
                retry_at = parsedate_to_datetime(value)
                if retry_at.tzinfo is None:
                    retry_at = retry_at.replace(tzinfo=timezone.utc)
                return max(0.0, (retry_at - datetime.now(timezone.utc)).total_seconds())
            except Exception:
                pass
    return min(0.5 * (2 ** attempt), 8.0)

def get_token():
    global request_count
    for attempt in range(20):
        try:
            req = Request(BASE + '/token', method='POST')
            with urlopen(req, timeout=15) as resp:
                request_count += 1
                return json.load(resp)['token']
        except HTTPError as e:
            request_count += 1
            if e.code == 429 or 500 <= e.code < 600:
                time.sleep(retry_delay(e.headers, attempt))
                continue
            raise
        except (URLError, TimeoutError):
            time.sleep(min(0.5 * (2 ** attempt), 8.0))
    raise RuntimeError('unable to obtain token after retries')

def api_get(path):
    global token, request_count
    for attempt in range(100):
        if token is None:
            token = [REDACTED_SECRET]
        try:
            req = Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
            with urlopen(req, timeout=15) as resp:
                request_count += 1
                return json.load(resp)
        except HTTPError as e:
            request_count += 1
            if e.code == 401:
                token = None
                continue
            if e.code == 429 or 500 <= e.code < 600:
                time.sleep(retry_delay(e.headers, attempt))
                continue
            raise
        except (URLError, TimeoutError):
            time.sleep(min(0.5 * (2 ** attempt), 8.0))
    raise RuntimeError(f'unable to fetch {path} after retries')

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
seen = set()
duplicates = 0
qualifying = []
page_path = '/orders?page=1'
pages = 0
expected_total_pages = None
while page_path is not None:
    payload = api_get(page_path)
    pages += 1
    page_num = payload['page']
    if page_num "'!= pages:
        raise RuntimeError(f'"'unexpected page: got {page_num}, expected {pages}')
    if expected_total_pages is None:
        expected_total_pages = payload['total_pages']
    elif payload['total_pages'] "'!= expected_total_pages:
        raise RuntimeError('"'total_pages changed during traversal')
    for order in payload['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        stamp = order['placed_at']
        if stamp.endswith('Z'):
            stamp = stamp[:-1] + '+00:00'
        placed = datetime.fromisoformat(stamp)
        if placed.tzinfo is None:
            raise RuntimeError(f'naive placed_at for order {oid}')
        placed_utc = placed.astimezone(timezone.utc)
        if order['status'] == 'shipped' and start <= placed_utc < end:
            qualifying.append(order)
    page_path = payload['next']

if pages "'!= expected_total_pages:
    raise RuntimeError(f'"'traversed {pages} pages, expected {expected_total_pages}')

customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = api_get('/customers/' + str(cid))
    customer = customers[cid]
    raw = Decimal(order['amount_cents']) * (Decimal(100) - Decimal(customer['discount_pct'])) / Decimal(100)
    discounted = int(raw.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    by_region[customer['region']] += discounted

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print(json.dumps({
    'result': result,
    'audit': {
        'pages': pages,
        'unique_orders_seen': len(seen),
        'customers_cached': len(customers),
        'requests_including_token': request_count,
    }
}, indent=2))
